css:
* { box-shadow: none !important; text-shadow: none !important; }
body { background: #f7f5ee !important; color: #232320 !important; font-family: 'Courier Prime',monospace !important; line-height: 1.55 !important; }
h1, h2, h3, h4 { font-family: 'Courier Prime',monospace !important; font-weight: 700 !important; color: #232320 !important; background: none !important; -webkit-text-fill-color: #232320 !important; line-height: 1.05 !important; letter-spacing: -0.02em !important; margin: 0 0 16px !important; text-transform: none !important; }
h1 { font-size: clamp(38px, 5.6vw, 68px) !important; }
h2 { font-size: clamp(26px, 3.4vw, 38px) !important; margin-top: 64px !important; }
p { margin: 0 0 14px !important; max-width: 64ch; }
section, header, main, footer, div, nav, p, li, span { background-image: none !important; }
[class*=card], [class*=Card] { background: #f7f5ee !important; border: 1px solid #232320 !important; border-radius: 0 !important; padding: 24px !important; }
[class*=card]:hover { border-color: #8f1f1f !important; }
.ug-ic { vertical-align: -3px; }
button, [class*=btn], [class*=Btn], a[class*=button], input[type=submit] { background: #232320 !important; color: #f7f5ee !important; border: 1px solid #232320 !important; border-radius: 0 !important; padding: 12px 24px !important; font-family: 'Courier Prime',monospace !important; font-weight: 600 !important; font-size: 13px !important; }
button:hover, [class*=btn]:hover { background: #8f1f1f !important; border-color: #8f1f1f !important; color: #8f1f1f !important; }
nav, header { border-bottom: 1px solid #232320 !important; }
a { color: #8f1f1f !important; }
img { border-radius: 0 !important; }
input, textarea, select { background: #f7f5ee !important; border: 1px solid #232320 !important; border-radius: 0 !important; color: #232320 !important; padding: 8px 12px !important; }
[class*=hero-visual], [class*=mockup], [class*=preview] { background: #f7f5ee !important; border: 1px solid #232320 !important; border-radius: 0 !important; padding: 24px !important; }
[class*=mock-row] { background: transparent !important; border-bottom: 1px solid #232320 !important; border-radius: 0 !important; margin-bottom: 0 !important; }
[class*=mock-bar] { background: #8f1f1f !important; }
[class*=mock-dot] { background: #8f1f1f !important; }
::selection { background: #8f1f1f; color: #f7f5ee; }
